<div class="page-head"><div><span class="eyebrow">ANALYSE</span><h1>Rapports & indicateurs</h1><p class="muted">Suivez les performances de votre entreprise.</p></div></div><div class="stats-grid"><div class="stat-card"><span>Marge brute estimée cumulée</span><strong><?= money($profit) ?></strong><small>Sur les ventes avec produits référencés</small></div><div class="stat-card"><span>Période analysée</span><strong>6 mois</strong><small>Chiffre d'affaires mensuel</small></div></div><section class="panel"><h2>Chiffre d'affaires par mois</h2><?php if(!$months): ?><div class="empty">Pas encore de données de vente.</div><?php else: ?><div class="bars"><?php $max=max(array_column($months,'total'))?:1;foreach($months as $m): ?><div class="bar-row"><span><?= e($m['month']) ?></span><div class="bar-track"><i style="width:<?= round($m['total']/$max*100) ?>%"></i></div><b><?= money($m['total']) ?></b></div><?php endforeach; ?></div><?php endif; ?></section>